const temp = parseFloat(msg.payload);
if (isNaN(temp)) return null;

const now = Date.now();
flow.set('current_temp', temp);
flow.set('last_temp_time', now);

// --- Track daily min/max ---
let dMin = flow.get('daily_min');
let dMax = flow.get('daily_max');
if (dMin === undefined || dMin === null) dMin = temp;
if (dMax === undefined || dMax === null) dMax = temp;
if (temp < dMin) flow.set('daily_min', temp);
if (temp > dMax) flow.set('daily_max', temp);

// ═══════════════════════════════════════
// Alert 1: High Temp >30°C (cooldown 30min)
// ═══════════════════════════════════════
if (temp > 30) {
    const last = flow.get('last_alert_high_temp') || 0;
    if (now - last > 1800000) {
        flow.set('last_alert_high_temp', now);
        flow.set('high_temp_recovered', false);
        return { payload: {
            title: '🔴 MROOM 高温报警!',
            message: '温度 ' + temp.toFixed(1) + '°C 超过 30°C！菌丝可能受损，请立即检查加热垫和传感器。',
            critical: true,
            id: 'high_temp'
        }};
    }
}

// Recovery after high temp
if (temp < 28 && (flow.get('last_alert_high_temp') || 0) > 0 && !flow.get('high_temp_recovered')) {
    flow.set('high_temp_recovered', true);
    return { payload: {
        title: '🟢 MROOM 温度已恢复',
        message: '温度回到 ' + temp.toFixed(1) + '°C，系统恢复正常。',
        critical: false,
        id: 'recovery'
    }};
}

// ═══════════════════════════════════════
// Alert 2: Heater Fault (cooldown 60min)
// Heater ON >15min but temp rise <0.5°C
// ═══════════════════════════════════════
const hOn = flow.get('heater_on') || false;
const hTime = flow.get('heater_on_time') || 0;
const hTemp = flow.get('heater_on_temp') || 0;

if (hOn && hTime > 0) {
    const dur = now - hTime;
    if (dur > 900000) {
        const rise = temp - hTemp;
        if (rise < 0.5) {
            const last = flow.get('last_alert_heater_fault') || 0;
            if (now - last > 3600000) {
                flow.set('last_alert_heater_fault', now);
                return { payload: {
                    title: '🟠 MROOM 加热垫疑似故障!',
                    message: '加热垫已运行 ' + Math.round(dur / 60000) + ' 分钟，温度仅变化 ' + rise.toFixed(1) + '°C (' + hTemp.toFixed(1) + ' → ' + temp.toFixed(1) + '°C)。请检查加热垫是否损坏。',
                    critical: false,
                    id: 'heater_fault'
                }};
            }
        }
    }
}

// ═══════════════════════════════════════
// Alert 3: Low Temp <20°C >30min (cooldown 120min)
// ═══════════════════════════════════════
if (temp < 20) {
    let start = flow.get('low_temp_start');
    if (!start) {
        flow.set('low_temp_start', now);
    } else if (now - start > 1800000) {
        const last = flow.get('last_alert_low_temp') || 0;
        if (now - last > 7200000) {
            flow.set('last_alert_low_temp', now);
            return { payload: {
                title: '🟠 MROOM 温度持续过低!',
                message: '温度 ' + temp.toFixed(1) + '°C 持续低于 20°C 超过 30 分钟。加热系统可能故障或环境温度异常。',
                critical: false,
                id: 'low_temp'
            }};
        }
    }
} else {
    flow.set('low_temp_start', null);
}

return null;

// Track heater ON/OFF state for fault detection
// Stores state in flow context for temp_alarm to read
const state = msg.payload;
const now = Date.now();
const temp = flow.get('current_temp') || 0;

if (state === 'on') {
    if (!flow.get('heater_on')) {
        flow.set('heater_on', true);
        flow.set('heater_on_time', now);
        flow.set('heater_on_temp', temp);
        // Increment daily heating cycle count
        const count = (flow.get('daily_heat_count') || 0) + 1;
        flow.set('daily_heat_count', count);
    }
} else {
    flow.set('heater_on', false);
    flow.set('heater_on_time', 0);
    flow.set('heater_on_temp', 0);
}

return null;

// Check if device has stopped sending data
// Triggers if no temp update for >5 minutes
const now = Date.now();
const lastTempTime = flow.get('last_temp_time') || 0;

// Skip check if we never received data yet
if (lastTempTime === 0) return null;

// Check for >5min stale data
if ((now - lastTempTime) > 300000) {
    const last = flow.get('last_alert_offline') || 0;
    // Cooldown: 30 minutes
    if (now - last > 1800000) {
        flow.set('last_alert_offline', now);
        const staleMins = Math.round((now - lastTempTime) / 60000);
        return { payload: {
            title: '🟡 MROOM 设备离线!',
            message: 'ESP32-S3 已 ' + staleMins + ' 分钟无数据更新。可能原因：WiFi断连 / 设备死机 / 停电。恒温器仍在本地独立运行。',
            critical: false,
            id: 'offline'
        }};
    }
} else {
    // Device is online, clear offline alert state
    flow.set('last_alert_offline', 0);
}

return null;

// Compile daily mushroom room status report
const temp = flow.get('current_temp');
const hOn = flow.get('heater_on') || false;
const count = flow.get('daily_heat_count') || 0;
const dMin = flow.get('daily_min');
const dMax = flow.get('daily_max');

const t = (temp !== undefined && temp !== null) ? temp.toFixed(1) + '°C' : 'N/A';
const mn = (dMin !== undefined && dMin !== null) ? dMin.toFixed(1) + '°C' : 'N/A';
const mx = (dMax !== undefined && dMax !== null) ? dMax.toFixed(1) + '°C' : 'N/A';
const st = hOn ? '🔥 加热中' : '💤 待机';

const message = '📊 每日蘑菇房状态报告\n━━━━━━━━━━━━━━━━\n🌡️ 当前温度: ' + t + '\n📈 今日最高: ' + mx + '\n📉 今日最低: ' + mn + '\n🔥 加热垫: ' + st + '\n🔄 今日加热次数: ' + count + ' 次';

// Reset daily counters
flow.set('daily_heat_count', 0);
flow.set('daily_min', null);
flow.set('daily_max', null);

return { payload: {
    title: '🍄 MROOM 每日报告',
    message: message,
    critical: false,
    id: 'daily_summary'
}};

// Route alerts to iOS Push + HA Persistent Notification
// Input: msg.payload = { title, message, critical, id }
const alert = msg.payload;
if (!alert || !alert.title) return [null, null];

// Output 1: iOS Push Notification
const iosMsg = {
    payload: {
        data: {
            title: alert.title,
            message: alert.message,
            data: {
                push: {
                    sound: alert.critical
                        ? { name: 'default', critical: 1, volume: 1.0 }
                        : { name: 'default' }
                }
            }
        }
    }
};

// Output 2: HA Persistent Notification
const haMsg = {
    payload: {
        data: {
            title: alert.title,
            message: alert.message,
            notification_id: 'mroom_' + (alert.id || 'alert')
        }
    }
};

return [iosMsg, haMsg];
